python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('ErrorMappingBpmn.bpmn')
print('Well-formed OK')
root = tree.getroot()
ns = {'bpmn':'http://www.omg.org/spec/BPMN/20100524/MODEL','bpmndi':'http://www.omg.org/spec/BPMN/20100524/DI','uipath':'http://uipath.org/schema/bpmn'}
ids = set()
for el in root.iter():
    i = el.get('id')
    if i: ids.add(i)
print('IDs:', sorted(ids))
# check refs
for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    s=sf.get('sourceRef'); t=sf.get('targetRef')
    assert s in ids, f'missing sourceRef {s}'
    assert t in ids, f'missing targetRef {t}'
for be in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}boundaryEvent'):
    a = be.get('attachedToRef')
    assert a in ids, f'missing attachedToRef {a}'
for ed in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}errorEventDefinition'):
    r = ed.get('errorRef')
    assert r in ids, f'missing errorRef {r}'
for em in root.iter('{http://uipath.org/schema/bpmn}error'):
    r = em.get('errorRef')
    assert r in ids, f'missing uipath:error errorRef {r}'
print('All refs resolve OK')
# shapes vs nodes
shapes = {s.get('bpmnElement') for s in root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape')}
edges = {s.get('bpmnElement') for s in root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge')}
nodes = {n.get('id') for n in root.iter() if n.tag.startswith('{http://www.omg.org/spec/BPMN/20100524/MODEL}') and n.get('id') and n.tag.split('}')[1] in ('startEvent','endEvent','serviceTask','boundaryEvent','sendTask','task','scriptTask')}
flows = {n.get('id') for n in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow')}
print('nodes missing shape:', nodes - shapes)
print('flows missing edge:', flows - edges)
"
